insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-ek-137","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In the external metallic circuit of a galvanic cell, electrons travel","options":["from the anode toward the cathode","from the cathode toward the anode","through the salt bridge as free electrons","in both directions at equal speed"],"answer_index":0,"explanation":"Oxidation releases electrons at the anode; they flow through the wire to the cathode, where reduction consumes them.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-138","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Standard electrode potential is an intensive quantity, so doubling the size of a half-cell","options":["leaves $E^\\circ$ unchanged","doubles $E^\\circ$","halves $E^\\circ$","makes $E^\\circ$ equal to $2F$"],"answer_index":0,"explanation":"Potential does not scale with the amount of electrode or electrolyte, unlike extensive $\\Delta G$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-139","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Among several half-cells, the strongest oxidising agent is the couple with the","options":["most positive standard reduction potential","most negative standard reduction potential","largest number of electrons in the half-reaction","smallest ionic charge"],"answer_index":0,"explanation":"A large positive $E^\\circ$ means the oxidised form is readily reduced, i.e. it is a strong oxidant.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-140","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A gas electrode such as the hydrogen electrode employs platinum chiefly as","options":["an inert surface on which the redox couple can exchange electrons","the species that is oxidised in place of hydrogen","a source of H$^+$ ions","the salt-bridge filling"],"answer_index":0,"explanation":"Pt is chemically inert here; it provides a conducting surface for $\\mathrm{H^+} / \\mathrm{H_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-141","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The EMF of a cell is the potential difference measured when","options":["no current is drawn (open-circuit condition)","a very large current is forced through the cell","the cell is short-circuited with a copper wire","the salt bridge is removed"],"answer_index":0,"explanation":"EMF is the reversible, zero-current voltage. A working current produces an IR drop, so the measured voltage is smaller.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-142","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If $E^\\circ(\\mathrm{Cu^{2+}/Cu}) = +0.34\\ \\mathrm{V}$ and $E^\\circ(\\mathrm{Zn^{2+}/Zn}) = -0.76\\ \\mathrm{V}$, $E^\\circ$ of the Daniell cell is","options":["$1.10\\ \\mathrm{V}$","$0.42\\ \\mathrm{V}$","$-1.10\\ \\mathrm{V}$","$0.34\\ \\mathrm{V}$"],"answer_index":0,"explanation":"$E^\\circ_{\\mathrm{cell}} = 0.34 - (-0.76) = 1.10\\ \\mathrm{V}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-143","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For the couples $\\mathrm{Ag^+/Ag}$ ($E^\\circ = +0.80\\ \\mathrm{V}$) and $\\mathrm{Zn^{2+}/Zn}$ ($E^\\circ = -0.76\\ \\mathrm{V}$), the anode of the spontaneous cell is","options":["zinc metal","silver metal","the Ag$^+$ solution","an inert platinum foil only"],"answer_index":0,"explanation":"The more negative couple is oxidised: Zn dissolves at the anode while Ag$^+$ is reduced.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-144","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The strongest reducing agent among Zn, Cu, Ag and H$_2$ (use $E^\\circ$: Zn $-0.76$, H $0.00$, Cu $+0.34$, Ag $+0.80\\ \\mathrm{V}$) is","options":["zinc","silver","copper","hydrogen gas"],"answer_index":0,"explanation":"The most negative reduction potential belongs to Zn$^{2+}$/Zn, so metallic zinc is the strongest reductant of the set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-145","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The standard Gibbs energy change of a cell reaction is related to $E^\\circ$ by","options":["$\\Delta G^\\circ = -nFE^\\circ$","$\\Delta G^\\circ = nFE^\\circ$","$\\Delta G^\\circ = -E^\\circ / nF$","$\\Delta G^\\circ = nF / E^\\circ$"],"answer_index":0,"explanation":"Electrical work available from a reversible cell is $nFE$; that work equals $-\\Delta G$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-146","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The notation $\\mathrm{Pt}|\\mathrm{Fe^{2+},Fe^{3+}}||\\mathrm{Ag^+}|\\mathrm{Ag}$ implies that the cell reaction is","options":["$\\mathrm{Fe^{2+} + Ag^+ \\rightarrow Fe^{3+} + Ag}$","$\\mathrm{Fe^{3+} + Ag \\rightarrow Fe^{2+} + Ag^+}$","$\\mathrm{Fe^{2+} + Ag \\rightarrow Fe^{3+} + Ag^+}$","$\\mathrm{2Fe^{3+} + Ag^+ \\rightarrow 2Fe^{2+} + Ag}$"],"answer_index":0,"explanation":"Left-hand side is oxidised (Fe$^{2+} \\to$ Fe$^{3+}$) and right-hand side is reduced (Ag$^+ \\to$ Ag).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-147","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In an electrolytic cell, as opposed to a galvanic cell, the anode is","options":["the positive electrode, still the site of oxidation","the negative electrode, the site of reduction","always made of zinc","unnecessary if a salt bridge is present"],"answer_index":0,"explanation":"Oxidation is always anodic. An external source makes the electrolytic anode positive, whereas a galvanic anode is negative.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-148","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A large positive $E^\\circ_{\\mathrm{cell}}$ corresponds to","options":["a large equilibrium constant for the cell reaction","a vanishingly small $K$","$K$ exactly equal to 1","no relation at all to $K$"],"answer_index":0,"explanation":"$\\Delta G^\\circ = -RT\\ln K = -nFE^\\circ$, so a sizable positive $E^\\circ$ means $K \\gg 1$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"cells-emf","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
